// ── Chuẩn hóa và làm sạch thông tin Lead đầu vào ─────────────────────────
const body = $input.first()?.json.body || $input.first()?.json || {};

const fullName = (body.full_name || body.name || 'Khách hàng').trim();
const companyName = (body.company_name || body.company || 'Doanh nghiệp chưa cập nhật').trim();
const email = (body.email || '').trim();
const phone = (body.phone || body.tel || '').trim();
const websiteUrl = (body.website_url || body.website || '').trim();
const industry = (body.industry || 'Chưa phân loại').trim();
const requirements = (body.project_requirements || body.message || body.requirements || 'Cần tư vấn thiết kế & phát triển website').trim();
const budget = Number(body.estimated_budget_vnd || body.budget) || 0;
const source = (body.source || 'Website Form Inbound').trim();

return [{
  json: {
    full_name: fullName,
    company_name: companyName,
    email: email,
    phone: phone,
    website_url: websiteUrl,
    industry: industry,
    project_requirements: requirements,
    estimated_budget_vnd: budget,
    source: source
  }
}];

