// ── Parse Lead Intelligence Brief ───────────────────────────────────────
const lead = $('Normalize Lead Data').first().json;
let rawAi = $input.first()?.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let ai = null;
if (rawAi) {
  let cleaned = String(rawAi).trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  }
  try {
    ai = JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { ai = JSON.parse(match[0]); } catch (err) {}
    }
  }
}

if (!ai) {
  ai = {
    lead_score: 70,
    classification: 'WARM',
    why_valuable: 'Tiềm năng cần khai thác thêm',
    company_assessment: 'Doanh nghiệp đang mở rộng',
    core_pain_point: lead.project_requirements,
    recommended_service: 'Corporate Website Redesign',
    suggested_sales_angle: 'Nhấn mạnh tốc độ và tối ưu chuyển đổi',
    urgency: 'MEDIUM'
  };
}

const score = Math.min(100, Math.max(0, parseInt(ai.lead_score) || 60));
const badge = score >= 80 ? '🔥 HOT' : score >= 50 ? '⭐ WARM' : '🌡️ COLD';

return [{
  json: {
    ...lead,
    lead_score: score,
    classification: ai.classification || (score >= 80 ? 'HOT' : score >= 50 ? 'WARM' : 'COLD'),
    score_badge: badge,
    sales_brief: ai
  }
}];

